#include <iostream>

/*
   @pre Tres nombres enters en una línia.
   @pos Si n'hi un dels tres que és igual al promig dels altres dos, escriu
	YES. En cas contrari, escriu NO.
*/
void	ft_equal_average(int a, int b, int c)
{
	if (2 * a == (b + c) || 2 * b == (a + c) || 2 * c == (a + b))
		std::cout  << "YES\n";
	else
		std::cout << "NO\n";
}

int	main(void)
{
	int nbr1, nbr2, nbr3;

	std::cin >> nbr1 >> nbr2 >> nbr3;
	ft_equal_average(nbr1, nbr2, nbr3);
	return (0);
}

