#include <iostream>

/* @Pre  n es el siguiente carácter, sin espacios, de una secuencia de
         ecuaciones de la forma t+t=t (cada t es un entero o la incógnita
         'x', que aparece una sola vez y puede estar a cualquier lado del
         '='), una ecuación por línea. Las llamadas se hacen en orden,
         un carácter por llamada, y tras la última línea se llama con
         n = '\n'.
   @Post Si n != '\n', se actualizan los acumuladores estáticos (a, b, c)
         con el carácter leído y no se escribe nada.
         Si n == '\n' y a != 0, se escribe en una línea el valor de x
         de la ecuación leída, (c - b) / a, y se reinician los
         acumuladores para la siguiente ecuación.
*/
void	ft_solv(char n)
{
	static int	a = 0, b = 0, c = 0;
	static int	value = 0, x = 0;
	static int	solve = 1, read = 0;

	if (n >= '0' && n <= '9')
	{
		value = value * 10 + (n - '0');
		x = 1;
	}
	else if (n == 'x')
	{
		if (read)
			solve = -solve;
		if (x)
			a += solve * value;
		else
			a += solve;
		value = x = 0;
		solve = 1;
	}
	else
	{
		if (x && read)
			c += solve * value;
		else if (x)
			b += solve * value;
		value = x = 0;
		solve = 1;
		if (n == '-')
			solve = -1;
		if (n == '=')
			read = 1;
		if (n == '\n')
		{
			if (a)
				std::cout << (c - b) / a << '\n';
			a = b = c = read = 0;
		}
	}
}

int	main(void)
{
	char	equacions;

	while (std::cin.get(equacions))
		ft_solv(equacions);
	ft_solv('\n');
	return (0);
}
